//! wp85: worldgen data packs against vanilla. A world whose packs replace a biome, add a biome to the overworld's list, bring noise
//! settings, a structure from a template of its own, a dimension type and dimensions must come out block by block (and biome by
//! biome) as vanilla's generation with the same packs: the case's chunks are generated by the vanilla server (tools/wp85/vgen85.py,
//! the worlds under `$KILN_WP85`, default `~/wp85/<case>`), by Kiln from the same packs in a world's `datapacks`, and compared.
//! Skipped without the vanilla data and the vanilla worlds. Vanilla itself is not deterministic for the features that span chunks, so a
//! second vanilla run (`<case>_b`) tells which blocks vanilla does not repeat; those are not held against Kiln.
//!
//! usage: python3 tools/wp85/vgen85.py <case> [_b] on the VM, then cargo test --release -p kiln-sim --test wp85_vanilla

use kiln_sim::{NoiseConfig, Sim, SimConfig};
use kiln_storage::AnvilSource;
use kiln_world::{ChunkPos, ChunkSource, Dimension};
use std::collections::HashSet;
use std::path::{Path, PathBuf};

fn vanilla_data() -> Option<PathBuf> {
    let dir = match std::env::var_os("KILN_DATAPACK").filter(|d| !d.is_empty()) {
        Some(d) => PathBuf::from(d),
        None => {
            let work = match std::env::var_os("KILN_WORK") {
                Some(d) if !d.is_empty() => PathBuf::from(d),
                _ => Path::new(env!("CARGO_MANIFEST_DIR")).join("../../work"),
            };
            work.join("generated")
        }
    };
    dir.join("reports/biome_parameters").is_dir().then_some(dir)
}

fn wp85_root() -> PathBuf {
    std::env::var_os("KILN_WP85")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(std::env::var_os("HOME").unwrap_or_default()).join("wp85"))
}

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for e in std::fs::read_dir(from).unwrap().flatten() {
        let (path, target) = (e.path(), to.join(e.file_name()));
        if path.is_dir() {
            copy_dir(&path, &target);
        } else {
            std::fs::copy(&path, &target).unwrap();
        }
    }
}

struct Case {
    packs: Vec<String>,
    seed: i64,
    areas: Vec<(String, i32, i32, i32, i32)>,
}

fn case(name: &str) -> Case {
    let text = std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tools/wp85/cases.json")).unwrap();
    let all: serde_json::Value = serde_json::from_str(&text).unwrap();
    let c = all.as_array().unwrap().iter().find(|c| c["name"] == name).unwrap_or_else(|| panic!("no case {name}"));
    Case {
        packs: c["packs"].as_array().unwrap().iter().map(|p| p.as_str().unwrap().to_owned()).collect(),
        seed: c["seed"].as_i64().unwrap(),
        areas: c["areas"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| (a[0].as_str().unwrap().to_owned(), a[1].as_i64().unwrap() as i32, a[2].as_i64().unwrap() as i32, a[3].as_i64().unwrap() as i32, a[4].as_i64().unwrap() as i32))
            .collect(),
    }
}

/// What differs in one area: blocks and biome cells.
#[derive(Default)]
struct Diff {
    chunks: usize,
    missing: usize,
    blocks: Vec<(i32, i32, i32)>,
    biomes: Vec<(i32, i32, i32)>,
    first: Vec<String>,
}

fn block_name(state: u16) -> String {
    kiln_data::blocks_types::block_of(state).name.to_owned()
}

/// Compares what `sim` generated with the vanilla world at `world` over the area; the chunks of the area must be loaded.
fn compare(sim: &Sim, world: &Path, dimension: &str, (x1, z1, x2, z2): (i32, i32, i32, i32), want_names: bool) -> Diff {
    let kind = kiln_data::levels::level_type(dimension).unwrap_or_else(|| panic!("no level {dimension}"));
    let dim = Dimension { min_y: kind.min_y, height: kind.height };
    let (ns, path) = dimension.split_once(':').unwrap();
    let mut anvil = AnvilSource::new(world.join("dimensions").join(ns).join(path).join("region"));
    anvil.dimension = dim;
    let mut diff = Diff::default();
    for cx in (x1 >> 4)..=(x2 >> 4) {
        for cz in (z1 >> 4)..=(z2 >> 4) {
            let Some(chunk) = anvil.load(ChunkPos::new(cx, cz), dim) else {
                diff.missing += 1;
                continue;
            };
            diff.chunks += 1;
            for y in kind.min_y..kind.min_y + kind.height {
                for lz in 0..16 {
                    for lx in 0..16 {
                        let (x, z) = (cx * 16 + lx, cz * 16 + lz);
                        let theirs = chunk.get(lx as usize, y, lz as usize);
                        let ours = sim.block_in(dimension, x, y, z);
                        if ours != Some(theirs) {
                            diff.blocks.push((x, y, z));
                            if want_names && diff.first.len() < 12 {
                                diff.first.push(format!("({x}, {y}, {z}) kiln {:?} vanilla {}", ours.map(block_name), block_name(theirs)));
                            }
                        }
                    }
                }
            }
            for (s, section) in chunk.sections.iter().enumerate() {
                for cell in 0..64usize {
                    let theirs = match &section.biomes {
                        kiln_world::section::Biomes::Single(b) => *b,
                        kiln_world::section::Biomes::Cells(c) => c[cell],
                    };
                    let (x, y, z) = (cx * 16 + (cell & 3) as i32 * 4, kind.min_y + s as i32 * 16 + (cell >> 4) as i32 * 4, cz * 16 + ((cell >> 2) & 3) as i32 * 4);
                    if sim.biome_in(dimension, x, y, z) != Some(theirs) {
                        diff.biomes.push((x, y, z));
                    }
                }
            }
        }
    }
    diff
}

fn run(name: &str) {
    let Some(datapack) = vanilla_data() else {
        eprintln!("skipped {name}: no vanilla data (KILN_DATAPACK or `cargo xtask data`)");
        return;
    };
    let vanilla = wp85_root().join(name).join("world");
    if !vanilla.join("level.dat").is_file() {
        eprintln!("skipped {name}: no vanilla world at {} (python3 tools/wp85/vgen85.py {name})", vanilla.display());
        return;
    }
    let baseline = wp85_root().join(format!("{name}_b")).join("world");
    let case = case(name);
    let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("wp85-{name}"));
    let _ = std::fs::remove_dir_all(&dir);
    for pack in &case.packs {
        copy_dir(&Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tools/wp85/packs").join(pack), &dir.join("datapacks").join(pack));
    }
    let mut config = SimConfig::new(4, 4, Some(dir.clone()));
    config.noise = Some(NoiseConfig { seed: case.seed, datapack, threads: 4 });
    let mut sim = Sim::new(config);
    assert!(sim.step([]));
    let mut problems = Vec::new();
    for (dimension, x1, z1, x2, z2) in &case.areas {
        let (cx1, cz1, cx2, cz2) = (x1 >> 4, z1 >> 4, x2 >> 4, z2 >> 4);
        for wx in (cx1..=cx2).step_by(16) {
            for wz in (cz1..=cz2).step_by(16) {
                let (ex, ez) = ((wx + 15).min(cx2), (wz + 15).min(cz2));
                sim.console_now(&format!("execute in {dimension} run forceload add {} {} {} {}", wx * 16, wz * 16, ex * 16 + 15, ez * 16 + 15));
            }
        }
        let area = (*x1, *z1, *x2, *z2);
        let d = compare(&sim, &vanilla, dimension, area, true);
        // Positions vanilla does not repeat itself.
        let unstable: HashSet<(i32, i32, i32)> =
            if baseline.join("level.dat").is_file() { compare_worlds(&vanilla, &baseline, dimension, area) } else { HashSet::new() };
        let blocks: Vec<_> = d.blocks.iter().filter(|p| !unstable.contains(p)).collect();
        eprintln!(
            "{name} {dimension}: {} chunks compared ({} missing in vanilla's world), {} blocks differ ({} of them differ between two vanilla runs), {} biome cells differ",
            d.chunks,
            d.missing,
            d.blocks.len(),
            d.blocks.len() - blocks.len(),
            d.biomes.len()
        );
        for line in &d.first {
            eprintln!("  {line}");
        }
        if d.chunks == 0 {
            problems.push(format!("{dimension}: no chunk of vanilla's world to compare"));
        }
        if !blocks.is_empty() || !d.biomes.is_empty() {
            problems.push(format!("{dimension}: {} blocks and {} biome cells differ from vanilla", blocks.len(), d.biomes.len()));
        }
    }
    drop(sim);
    let _ = std::fs::remove_dir_all(&dir);
    assert!(problems.is_empty(), "{name}: {problems:?}");
}

/// The block positions where two vanilla worlds differ over the area.
fn compare_worlds(a: &Path, b: &Path, dimension: &str, (x1, z1, x2, z2): (i32, i32, i32, i32)) -> HashSet<(i32, i32, i32)> {
    let kind = kiln_data::levels::level_type(dimension).unwrap();
    let dim = Dimension { min_y: kind.min_y, height: kind.height };
    let (ns, path) = dimension.split_once(':').unwrap();
    let open = |w: &Path| {
        let mut s = AnvilSource::new(w.join("dimensions").join(ns).join(path).join("region"));
        s.dimension = dim;
        s
    };
    let (mut sa, mut sb) = (open(a), open(b));
    let mut out = HashSet::new();
    for cx in (x1 >> 4)..=(x2 >> 4) {
        for cz in (z1 >> 4)..=(z2 >> 4) {
            let (Some(ca), Some(cb)) = (sa.load(ChunkPos::new(cx, cz), dim), sb.load(ChunkPos::new(cx, cz), dim)) else { continue };
            for y in kind.min_y..kind.min_y + kind.height {
                for lz in 0..16 {
                    for lx in 0..16 {
                        if ca.get(lx, y, lz) != cb.get(lx, y, lz) {
                            out.insert((cx * 16 + lx as i32, y, cz * 16 + lz as i32));
                        }
                    }
                }
            }
        }
    }
    out
}

